require 'async/http/protocol'

module Fluent
  module PluginHelper
    module HttpServer
      class Router
        class NotFoundApp
          def self.call(req)
            [404, { 'Content-Type' => 'text/plain' }, "404 Not Found\n"]
          end
        end

        attr_reader :get_routes, :head_routes, :post_routes, :put_routes, :patch_routes, :other_routes

        def initialize(default_app = nil)
          @get_routes = {}
          @head_routes = {}
          @post_routes = {}
          @put_routes = {}
          @patch_routes = {}
          @other_routes = { delete: {}, connect: {}, options: {}, trace: {} }
          @default_app = default_app || NotFoundApp
        end

        # @param method [Symbol]
        # @param path [String]
        # @param request [Fluent::PluginHelper::HttpServer::Request]
        def route!(method, path, request)
          table =
            case method
            when :get
              @get_routes
            when :head
              @head_routes
            when :post
              @post_routes
            when :put
              @put_routes
            when :patch
              @patch_routes
            else
              @other_routes.fetch(method)
            end
          table.fetch(path, @default_app).call(request)
        end
      end
    end
  end
end

